mapper.select:
SELECT u.id,u.`name`,u.`name` as username,u.phone,u.age,u.user_no as userNo, u.`status`,ds.name as statusName, u.gender,CASE WHEN u.gender='1' THEN '男' ELSE '女' END as genderName, u.birthday,u.address,u.grade,u.classs,cc.title as className,cg.title as gradeName, concat(cg.title, ' ', cc.title) as gradeClassName, u.create_time as createTime,u.update_time as updateTime
from user u left join course cg on cg.id=u.grade left join course cc on cc.id=u.classs left join sys_dictionary ds on ds.id=u.status
and u.name like concat('%',#{user.name},'%')
and u.grade=#{user.grade}
and u.classs=#{user.classs}
and u.status=#{user.status}
and u.classs in
#{item}
order by cg.sort_by asc,cc.sort_by asc,u.create_time desc
